/**
 * @file ai_pid_hadron.cpp
 * @brief Ai Pid Hadron analysis for CLAS12 data
 *
 * Generated by create_analysis.py
 */

#include <clas12/framework/Core.hpp>
#include <clas12/framework/core/ApplicationBuilder.hpp>
#include <clas12/CLAS12.hpp>
#include <clas12/algorithms/selection/DISSelectionAlg.hpp>
#include <clas12/algorithms/selection/ElectronSelectionAlg.hpp>
#include <clas12/framework/services/FiducialService.hpp>

#include <cxxopts.hpp>
#include <fmt/format.h>

#include <string>
#include <vector>

// Include your custom algorithm headers here
#include "AiPidHadronAlg.hpp"

auto main(int argc, char* argv[]) -> int {
    // Parse command line arguments
    cxxopts::Options options("ai_pid_hadron", "Ai Pid Hadron analysis for CLAS12 data");

    
        options.add_options()
        ("h,help", "Show help")
        ("i,input", "Input HIPO files", cxxopts::value<std::string>())
        ("o,output", "Output ROOT file", cxxopts::value<std::string>()->default_value("ai_pid_hadron_output.root"))
        ("p,percentage", "Percentage of events to process", cxxopts::value<double>()->default_value("100"))
        ("t,threads", "Number of threads to use", cxxopts::value<int>()->default_value("1"))
        ("target", "Target (e.g., LD2, C, Fe)", cxxopts::value<std::string>()->default_value("LD2"))
        ("polarity", "Polarity (Out, In)", cxxopts::value<std::string>()->default_value("Out"))
        ("truth-mode", "Truth PID mode: 'rich' or 'exclusive'", cxxopts::value<std::string>()->default_value("rich"))
        ;

    options.parse_positional({"input"});
    options.positional_help("<input_files...>");

    auto result = options.parse(argc, argv);

    if (result.count("help") || !result.count("input")) {
        fmt::print("{}\n", options.help());
        return result.count("help") ? 0 : 1;
    }

    auto output_file = result["output"].as<std::string>();
    auto percentage = result["percentage"].as<double>();
    auto num_threads = result["threads"].as<int>();
    auto target = result["target"].as<std::string>();
    auto polarity = result["polarity"].as<std::string>();
    auto truth_mode = result["truth-mode"].as<std::string>();

    std::string input_str = result["input"].as<std::string>();
    std::vector<std::string> input_files;
    if (!input_str.empty()) {
        if (std::filesystem::is_directory(input_str)) {
            input_files = clas12::FileUtils::read_recursive_hipo_files(input_str);
        } else if (input_str.find(',') != std::string::npos) {
            input_files = clas12::StringUtils::split(input_str, ',');
        } else {
            input_files = {input_str};
        }
    } else {
        clas12::framework::Log::error("Main", "Please provide input files or directories.");
        return EXIT_FAILURE;
    }

    auto app = clas12::framework::make_application("AI Pid Hadron Analysis")
        .with_input_files(input_files)
        .with_output(output_file)
        .with_percentage(percentage)
        .with_threads(num_threads)
        .with_standard_services()
        .with_beam_energy(10.53)
        .add_service<clas12::framework::ElectronCutsService>()
        .add_service<clas12::framework::FiducialService>()
        .add_algorithm<clas12::algorithms::ElectronSelectionAlg>("ElectronSelectionAlg", clas12::string_to_target(target), clas12::string_to_polarity(polarity))
        .add_algorithm<clas12::algorithms::DISSelectionAlg>("DISSelection")
        .add_algorithm<ai_pid_hadron::AiPidHadronAlg>("AiPidHadronAlg", truth_mode)
        .build();
    
    // Initialize
    if (auto sc = app.initialize(); sc.is_failure()) {
        fmt::print(stderr, "Error: Initialization failed: {}\n", sc.message());
        return 1;
    }

    // Run event loop
    if (auto sc = app.run(); sc.is_failure()) {
        fmt::print(stderr, "Error: Processing failed\n");
        return 1;
    }

    // Finalize
    app.finalize();

    fmt::print("Analysis complete. Output: {}\n", output_file);
    return 0;
}
